package com.paitrick.blog.category.controller; import com.paitrick.blog.category.*; import com.paitrick.blog.category.domain.Category; import com.paitrick.blog.category.dto.CategoryRequest; import com.paitrick.blog.category.service.CategoryService; import com.paitrick.blog.common.response.ApiResponse; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class CategoryController{private final CategoryService s;public CategoryController(CategoryService s){this.s=s;}@GetMapping("/categories") ApiResponse<List<Category>> all(){return ApiResponse.ok(s.all());}@PostMapping("/admin/categories") ApiResponse<Category> create(@Valid @RequestBody CategoryRequest r){return ApiResponse.ok(s.create(r));}@PutMapping("/admin/categories/{id}") ApiResponse<Category> update(@PathVariable long id,@Valid @RequestBody CategoryRequest r){return ApiResponse.ok(s.update(id,r));}@DeleteMapping("/admin/categories/{id}") ApiResponse<Void> delete(@PathVariable long id){s.delete(id);return ApiResponse.ok(null);}}
